import{_ as o,o as r,c as a,a2 as d}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"9.4 电工识图基础","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-4-dian-gong-shi-tu-ji-chu.md","filePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-4-dian-gong-shi-tu-ji-chu.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-4-dian-gong-shi-tu-ji-chu.md"};function n(l,t,e,s,g,h){return r(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="_9-4-电工识图基础" tabindex="-1">9.4 电工识图基础 <a class="header-anchor" href="#_9-4-电工识图基础" aria-label="Permalink to &quot;9.4 电工识图基础&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电工图纸是&quot;电气世界的说明书&quot;。这一节掌握三类电气图、常用图形符号和文字符号,学会怎么&quot;看图&quot;——这是读懂电路、正确接线的基础,也是考试必考点。</p><h2 id="一、电气图的三种主要形式" tabindex="-1">一、电气图的三种主要形式 <a class="header-anchor" href="#一、电气图的三种主要形式" aria-label="Permalink to &quot;一、电气图的三种主要形式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形式</th><th>画什么</th><th>用途</th></tr></thead><tbody><tr><td><strong>电路原理图</strong></td><td>用符号表示电路连接关系、工作原理</td><td>分析电路、看原理</td></tr><tr><td><strong>接线图(安装图)</strong></td><td>表示元件实际安装位置和接线</td><td>现场接线、安装</td></tr><tr><td><strong>布置图(位置图)</strong></td><td>表示设备、元件的平面位置</td><td>规划安装位置</td></tr></tbody></table><blockquote><p>💡 原理图&quot;讲道理&quot;,接线图&quot;讲怎么接&quot;,布置图&quot;讲装哪&quot;。</p></blockquote><h2 id="二、常用电气图形符号-必背" tabindex="-1">二、常用电气图形符号(必背) <a class="header-anchor" href="#二、常用电气图形符号-必背" aria-label="Permalink to &quot;二、常用电气图形符号(必背)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元件</th><th>图形符号(简记)</th><th>文字符号</th></tr></thead><tbody><tr><td>电动机</td><td>圆圈内 M</td><td><strong>M</strong></td></tr><tr><td>变压器</td><td>两个绕组线圈</td><td><strong>T</strong></td></tr><tr><td>熔断器</td><td>方框内 X/矩形中一横</td><td><strong>FU</strong></td></tr><tr><td>断路器(低压)</td><td>带触点的开关</td><td><strong>QF</strong></td></tr><tr><td>隔离开关</td><td>刀开关</td><td><strong>QS</strong></td></tr><tr><td>接触器</td><td>方框表示线圈,<strong>KM</strong>;触点另画</td><td><strong>KM</strong></td></tr><tr><td>热继电器</td><td>方框内 L/加热元件</td><td><strong>FR</strong></td></tr><tr><td>中间/时间继电器</td><td>方框内 KA/KT</td><td><strong>KA / KT</strong></td></tr><tr><td>按钮(启动/停止)</td><td>常开/常闭按钮</td><td><strong>SB</strong></td></tr><tr><td>行程开关</td><td>限位开关</td><td><strong>SQ</strong></td></tr><tr><td>电流互感器</td><td>两个铁芯圈</td><td><strong>TA(CT)</strong></td></tr><tr><td>电压互感器</td><td>两个铁芯圈</td><td><strong>TV(PT)</strong></td></tr><tr><td>信号灯</td><td>圆圈内 X(红/绿)</td><td><strong>HL</strong></td></tr><tr><td>整流二极管</td><td>三角+竖线</td><td><strong>V</strong></td></tr></tbody></table><blockquote><p>⚠️ 高频判断:<strong>接触器用 KM,热继电器用 FR,熔断器用 FU,断路器用 QF,按钮用 SB</strong>,这些文字符号必须记牢。</p></blockquote><h2 id="三、三相电源线路的标注" tabindex="-1">三、三相电源线路的标注 <a class="header-anchor" href="#三、三相电源线路的标注" aria-label="Permalink to &quot;三、三相电源线路的标注&quot;">​</a></h2><ul><li>相线:<strong>L1、L2、L3</strong>(旧标 A、B、C 或黄、绿、红);</li><li>中性线:<strong>N</strong>(淡蓝色);</li><li>保护零线:<strong>PE</strong>(黄绿双色);</li><li>电气设备接线端子常用:<strong>U、V、W</strong>(三相绕组端),数字表示辅助触点编号。</li></ul><h2 id="四、怎么-看图-的步骤" tabindex="-1">四、怎么&quot;看图&quot;的步骤 <a class="header-anchor" href="#四、怎么-看图-的步骤" aria-label="Permalink to &quot;四、怎么&quot;看图&quot;的步骤&quot;">​</a></h2><ol><li><strong>先看主电路(一次回路)</strong>:从电源 → 开关 → 熔断器/断路器 → 接触器主触点 → 热继电器 → 电动机,弄清楚&quot;电走哪条路&quot;;</li><li><strong>再看控制电路(二次回路)</strong>:从一根电源线 → 按钮 → 接触器线圈 → 回到另一根电源线,弄清楚&quot;怎么控制&quot;;</li><li><strong>找关联</strong>:看接触器 KM 的辅助触点在哪里,热继电器 FR 的常闭触点串在控制电路哪里;</li><li><strong>看保护</strong>:漏电保护、短路保护、过载保护是怎么接的。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主电路: L1→QS→FU→KM主触点→FR→M</span></span>
<span class="line"><span>控制电路: L→SB1→SB2→KM线圈→FR常闭→L</span></span>
<span class="line"><span>         (按钮启动 停止 接触器 过载保护)</span></span></code></pre></div><blockquote><p>💡 看懂一个图的诀窍:<strong>主电路看&quot;谁给电动机送电&quot;,控制电路看&quot;谁让主电路通断&quot;</strong>。</p></blockquote><h2 id="五、电路图中-线-的颜色与粗细" tabindex="-1">五、电路图中&quot;线&quot;的颜色与粗细 <a class="header-anchor" href="#五、电路图中-线-的颜色与粗细" aria-label="Permalink to &quot;五、电路图中&quot;线&quot;的颜色与粗细&quot;">​</a></h2><ul><li>主电路导线通常画<strong>粗实线</strong>,控制电路画细实线;</li><li>不同功能回路用不同编号、不同颜色区分。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 图形符号:电动机 M、变压器 T、熔断器 FU、断路器 QF、隔离开关 QS、接触器 KM、热继电器 FR、按钮 SB。</li><li>✅ 相线 L1L2L3、中性线 N、保护线 PE。</li><li>✅ 看图顺序:先主电路、后控制电路。</li><li>⚠️ 易混点:KM(接触器)与 KA(继电器)、QF(断路器)与 QS(隔离开关)的文字符号别记混。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>电气图有原理图、接线图、布置图三种。</li><li>记住常用元件的图形符号和文字符号。</li><li>看图先看主电路、再看控制电路、再找关联与保护。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(单选)表示接触器的文字符号是()。 A. KM　B. KA　C. FR　D. FU</li><li>(单选)熔断器的文字符号是()。 A. QF　B. QS　C. FU　D. FV</li><li>(判断)电路原理图用来分析电路工作原理,接线图用来指导实际接线。( )</li><li>(单选)三相电源相线的标注是()。 A. U、V、W　B. L1、L2、L3　C. N、PE、PEN　D. A、B、C 或 L1、L2、L3</li><li>(判断)看电气图时应先看主电路,再看控制电路。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>A</strong>。接触器文字符号是 KM。</li><li><strong>C</strong>。熔断器是 FU。</li><li><strong>√</strong>。原理图分析原理,接线图指导接线。</li><li><strong>B</strong>。三相相线标 L1、L2、L3(旧标 A、B、C)。</li><li><strong>√</strong>。先主电路、后控制电路是看图顺序。</li></ol></details>`,24)])])}const q=o(i,[["render",n]]);export{c as __pageData,q as default};
